<template><nav :class="['nav',scrolled?'scrolled':'']"><div class="nav-inner"><router-link to="/" class="brand"><img src="../assets/img/transparent-logo1.png" alt="Sophor"><span>SOPHOR<small>TECHNOLOGIES PLC</small></span></router-link><div class="links"><router-link v-for="l in nav" :key="l.to" :to="l.to">{{l.label}}</router-link></div><div class="actions"><router-link to="/login" class="login">Staff login</router-link><router-link to="/contact" class="book">Book a consultation ↗</router-link></div><button class="toggle" @click="open=!open" aria-label="Toggle menu"><i :class="open?'fas fa-times':'fas fa-bars'"></i></button></div><div v-if="open" class="mobile"><router-link v-for="l in nav" :key="l.to" :to="l.to" @click="open=false">{{l.label}}</router-link><router-link to="/login" @click="open=false">Staff login</router-link></div></nav></template>
